<div id="login-screen" style="display:flex;position:fixed;inset:0;background:var(--dk);z-index:10000;align-items:center;justify-content:center;flex-direction:column;gap:0;">
<div style="background:var(--cd);border:1px solid var(--br2);border-radius:14px;width:100%;max-width:380px;padding:36px 32px;margin:16px;">
<div style="text-align:center;margin-bottom:28px;">
<img alt="MH3" src="data:image/jpeg;base64," style="max-width:280px;max-height:80px;object-fit:contain;display:inline-block;"/>
<div style="font-size:10px;color:var(--mt);letter-spacing:2px;text-transform:uppercase;margin-top:4px;">Sistema de Gestão · João Monlevade/MG</div>
</div>
<div id="login-erro" style="display:none;background:var(--rg);border:1px solid rgba(200,16,46,.3);color:#ff6b81;border-radius:6px;padding:9px 12px;font-size:12px;margin-bottom:14px;text-align:center;"></div>
<div id="lg-offline-msg" style="display:none;background:rgba(245,158,11,.15);border:1px solid rgba(245,158,11,.45);color:#d97706;border-radius:6px;padding:10px 12px;font-size:12px;font-weight:600;margin-bottom:14px;text-align:center;font-family:'Barlow',sans-serif;">⚠️ Sistema offline — entre em contato com o suporte.</div>
<div style="margin-bottom:14px;">
<label style="display:block;font-size:9px;font-weight:700;color:var(--mt);text-transform:uppercase;letter-spacing:1.2px;margin-bottom:5px;font-family:'Barlow Condensed',sans-serif;">Usuário</label>
<input autocomplete="username" id="lg-user" onkeydown="if(event.key==='Enter')document.getElementById('lg-pass').focus()" placeholder="Seu login" style="width:100%;background:var(--cd2);border:1px solid var(--br);border-radius:6px;color:var(--tx);padding:10px 13px;font-size:14px;font-family:'Barlow',sans-serif;outline:none;" type="text"/>
</div>
<div style="margin-bottom:22px;">
<label style="display:block;font-size:9px;font-weight:700;color:var(--mt);text-transform:uppercase;letter-spacing:1.2px;margin-bottom:5px;font-family:'Barlow Condensed',sans-serif;">Senha</label>
<div style="position:relative;">
<input autocomplete="current-password" id="lg-pass" onkeydown="if(event.key==='Enter')fazerLogin()" placeholder="Sua senha" style="width:100%;background:var(--cd2);border:1px solid var(--br);border-radius:6px;color:var(--tx);padding:10px 13px;font-size:14px;font-family:'Barlow',sans-serif;outline:none;" type="password"/>
<button id="lg-eye" onclick="toggleSenhaLogin()" style="position:absolute;right:10px;top:50%;transform:translateY(-50%);background:none;border:none;color:var(--mt);cursor:pointer;font-size:16px;">👁</button>
</div>
</div>
<div style="margin-bottom:18px;display:flex;align-items:center;gap:8px;">
<input id="lg-salvar" style="width:16px;height:16px;cursor:pointer;accent-color:var(--red);" type="checkbox"/>
<label for="lg-salvar" style="font-size:12px;color:var(--mt);cursor:pointer;font-family:'Barlow',sans-serif;">Salvar usuário e senha neste computador</label>
</div>
<button id="lg-btn" onclick="fazerLogin()" style="width:100%;background:var(--red);color:white;border:none;border-radius:7px;padding:12px;font-size:14px;font-weight:700;cursor:pointer;font-family:'Barlow',sans-serif;letter-spacing:.5px;transition:background .15s;">Entrar no Sistema</button>
<div style="text-align:center;margin-top:18px;font-size:10px;color:var(--mt);">MH3 Rental · João Monlevade/MG · CNPJ: 26.881.195/0001-10<br/><span id="login-build" style="opacity:.85">🔄 Última atualização: —</span></div>
</div>
</div>
